class Solution {
    findOrder(numCourses, prerequisites) {
        const indegree = new Array(numCourses).fill(0);
        const adj = Array.from({ length: numCourses }, () => []);
        for (const [src, dst] of prerequisites) {
            indegree[dst]++;
            adj[src].push(dst);
        }

        const q = [];
        for (let n = 0; n < numCourses; n++) {
            if (indegree[n] === 0) {
                q.push(n);
            }
        }

        let finish = 0;
        const output = [];
        while (q.length > 0) {
            const node = q.shift();
            output.push(node);
            finish++;
            for (const nei of adj[node]) {
                indegree[nei]--;
                if (indegree[nei] === 0) {
                    q.push(nei);
                }
            }
        }

        if (finish !== numCourses) {
            return [];
        }
        return output.reverse();
    }
}

